const { waiverStanding, inertWaiverDiagnostic } = await import(`${repo}/src/domain/compat.ts`);
const { MUTATE_OPTIONS } = await import(`${repo}/src/app/operations/mutate-options.ts`);
const OLD = '11111111-1111-4111-8111-111111111111';
const LIVE = '22222222-2222-4222-8222-222222222222';
