const hash = requirementsContentHash(built.document,[LIVE]);
const evidence=[];
for (const shape of ['requirementId','requirementIds']) {
  const scope = id => shape === 'requirementId' ? {requirementId:id} : {requirementIds:[id]};
  const target = {code:CODE,...scope(OLD),contentHash:`sha256:${'0'.repeat(64)}`,reason:'review of deleted requirement'};
  const sibling = {code:CODE,...scope(LIVE),contentHash:hash,reason:'review of current requirement'};
  const raw = {...built.document,waivers:[target,sibling]};
  const document=(await Effect.runPromise(decodeDocument(raw))).document;
  const standing = waiverStanding(document,target);
  assert.equal(standing.kind,'inert');
  assert.equal(standing.cause,'missing-requirement');
  assert.equal(waiverStanding(document,sibling).kind,'qualifies');
  const diagnostic = inertWaiverDiagnostic(document,target,standing,[]);
  writeFileSync(`${scratch}/repro-${shape}.json`,JSON.stringify(document,null,2));
