  const after = foldOps(document,diagnostic.ops,time,MUTATE_OPTIONS);
  // Observe the defect; don't invert its assertion into a passing release test.
  assert.deepEqual(after.document.waivers,[target]);
  assert.notDeepEqual(after.document.waivers,[sibling]);
  evidence.push({shape,decode:'accepted',standing,ops:diagnostic.ops,expectedRemaining:[sibling],actualRemaining:after.document.waivers,summary:after.summary});
}
